using System.Diagnostics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using TextAnalysis;

const int WarmupIterations = 50;
const int BenchmarkIterations = 200;
int[] wordCounts = [100, 1000];

Console.WriteLine($"Runtime: {RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"OS: {RuntimeInformation.OSDescription}");
Console.WriteLine($"Warmup: {WarmupIterations} iterations, Benchmark: {BenchmarkIterations} iterations");
Console.WriteLine();
Console.WriteLine($"{"Method",-25} {"WordCount",10} {"Mean (ns)",15} {"StdDev (ns)",15} {"Allocated",12}");
Console.WriteLine(new string('-', 77));

foreach (int wordCount in wordCounts)
{
    var analyzer = CreateAnalyzer(wordCount);

    RunBenchmark("AverageWordLength", wordCount, () => analyzer.AverageWordLength());
    RunBenchmark("WordLengthHistogram", wordCount, () => analyzer.WordLengthHistogram());
    RunBenchmark("UniqueWordCount", wordCount, () => analyzer.UniqueWordCount());
}

static TextAnalyzer CreateAnalyzer(int wordCount)
{
    var rng = new Random(42);
    var words = new string[wordCount];
    for (int i = 0; i < wordCount; i++)
    {
        int len = rng.Next(1, 15);
        var chars = new char[len];
        for (int j = 0; j < len; j++)
            chars[j] = (char)('a' + rng.Next(0, 26));
        words[i] = new string(chars);
    }
    return new TextAnalyzer(string.Join(' ', words));
}

static void RunBenchmark<T>(string name, int wordCount, Func<T> action)
{
    // Warmup
    for (int i = 0; i < WarmupIterations; i++)
        action();

    // Collect per-iteration timings
    var timings = new double[BenchmarkIterations];
    long memBefore = GC.GetTotalAllocatedBytes(precise: true);

    for (int i = 0; i < BenchmarkIterations; i++)
    {
        long start = Stopwatch.GetTimestamp();
        action();
        long end = Stopwatch.GetTimestamp();
        timings[i] = (double)(end - start) / Stopwatch.Frequency * 1e9;
    }

    long memAfter = GC.GetTotalAllocatedBytes(precise: true);
    double allocPerOp = (double)(memAfter - memBefore) / BenchmarkIterations;

    double mean = timings.Average();
    double stddev = Math.Sqrt(timings.Select(t => (t - mean) * (t - mean)).Average());

    Console.WriteLine($"{name,-25} {wordCount,10} {mean,15:F1} {stddev,15:F1} {allocPerOp,10:F0} B");
}

